    private static final double[] MAX_JUMP_HEIGHTS = {1.2491870787446828D, 1.8229914290304237D, 2.495504135427751D, 3.262979208689927D, 4.121780657759501D, 5.068380817939499D, 6.09935681691951D, 7.211386509209021D, 8.401247360588883D, 9.665813316670295D, 11.00205067446683D, 12.40702172138586D, 13.877873208335501D, 15.411839932915072D, 17.00623904858685D, 18.600076567816984D, 20.320436142409292D, 22.09475148051476D, 23.920602111211082D, 25.795652703139638D, 27.71764149877518D, 29.638742958312946D, 31.66704373015527D, 33.73672487314393D, 35.84575686484723D, 36.42330700836513D, 40.15228283711707D, 42.390953289857094D, 44.6078684568749D, 46.93469415176959D, 49.29112651218843D, 51.618257282853605D, 54.05607596071225D};
    private static final int MAX_JUMP_HEIGHT_INDEX = 32;

    public static double boatVerticalSpeed(int events) {
        final int boundedEvents = Math.max(4, Math.min(events, 20));
        return (double) -0.04F * (boundedEvents + 1);
    }

    public static double flightVerticalLimit(int jumpAmplifier, int fallingTicks, boolean slowFalling) {
        int profile = jumpAmplifier;
        if (profile < 0 || profile >= PROFILE_COUNT) profile = 6;
        if (fallingTicks <= 0) {
            return slowFalling ? SLOW_FALLING_FALLBACK : NORMAL_FALLBACK;
        }
        if (slowFalling) {
            double[] table = SLOW_VERTICAL_LIMITS[profile];
            if (fallingTicks >= table.length) return SLOW_FALLING_FALLBACK;
            double v = table[fallingTicks];
            return Double.isNaN(v) ? SLOW_FALLING_FALLBACK : v;
        } else {
            double[] table = NORMAL_VERTICAL_LIMITS[profile];
            if (fallingTicks >= table.length) return NORMAL_FALLBACK;
            double v = table[fallingTicks];
            return Double.isNaN(v) ? NORMAL_FALLBACK : v;
        }
    }

    public static double maxJumpHeight(int jumpAmplifier) {
        if (jumpAmplifier < 0 || jumpAmplifier > MAX_JUMP_HEIGHT_INDEX) return Double.MAX_VALUE;
        double v = MAX_JUMP_HEIGHTS[jumpAmplifier];
        return Double.isNaN(v) ? Double.MAX_VALUE : v;
    }
